// The mechanism tree's pure parts (docs/plans/mechanism-tree.md piece T1): the forward subgraph, the loop boxes and
// Tarjan's components, the generations by longest path once the feedback edges are set aside, and stable ordering, on
// a small fixture and on the registry the page draws (registry-data.ts, generated by scripts/couplings.ts).
import { describe, expect, it } from 'vitest';
import { clinicalLabel } from './clinical.ts';
import { components, DEPTH, deviceModule, drawClass, forward, MAX_CHILDREN, mechanismTree, PATH_SLACK, view, type LoopDecl, type TreeData, type TreeRow } from './graph.ts';
import { generations, layout } from './layout.ts';
import { REGISTRY } from './registry-data.ts';
import { treeSvg } from './svg.ts';

const row = (id: string, from: string[], to: string, extra: Partial<TreeRow> = {}): TreeRow =>
  ({ id, module: 'm', from, to, sign: '+', form: 'factor', cls: 'UNTAGGED', consts: [], note: id, ...extra });
// T → a → [s1 → s2] (a reflex) → b → a (feedback through the plant); a → c (fitted); d is never reached
const FIX: TreeData = {
  triggers: [{ path: 'trigger.t', label: 'T' }],
  nodes: [{ path: 'trigger.t', kind: 'trigger', label: 'T' }, { path: 'x.absent', kind: 'effector', label: 'Missing', absent: 'research/44 L2-01' }],
  rows: [
    row('r1', ['trigger.t'], 'a'),
    row('r2', ['a'], 'rx.s1'),
    row('r3', ['rx.s1'], 'rx.s2'),
    row('r4', ['rx.s2'], 'b', { cls: 'FIT', consts: [{ name: 'G', value: '1', source: `[FIT: x]` }] }),
    row('r5', ['b'], 'a'),
    row('r6', ['a'], 'c', { cls: 'SOURCED', consts: [{ name: 'K', value: '2', source: 'Guyton 1955' }] }),
    row('r7', ['a'], 'c', { cls: 'FIT', consts: [{ name: 'F', value: '3', source: `[FIT: y]` }] }),
    row('r8', ['b'], 'x.absent', { cls: 'ABSENT', absent: 'research/44 L2-01' }),
    row('r9', ['d'], 'a'),
  ],
};
const RX: LoopDecl[] = [{ id: 'loop.rx', label: 'Reflex', members: (p) => p.startsWith('rx.') }];

describe('forward(): the reachable subgraph', () => {
  it('reaches what the trigger reaches, breadth first, and only the edges from reached nodes', () => {
    const s = forward(FIX, 'trigger.t');
    expect(s.nodes).toEqual(['trigger.t', 'a', 'rx.s1', 'c', 'rx.s2', 'b', 'x.absent']);
    expect(s.edges.map((e) => e.row.id)).toEqual(['r1', 'r2', 'r3', 'r4', 'r5', 'r6', 'r7', 'r8']);
  });
});

describe('mechanismTree(): loop boxes, merged edges, classes, feedback', () => {
  const tree = mechanismTree(FIX, 'trigger.t', () => null, RX);
  it('collapses the declared reflex into one loop box holding its states; its inner rows are kept', () => {
    expect(tree.nodes.map((n) => `${n.id}:${n.kind}`)).toEqual(['trigger.t:trigger', 'a:state', 'loop.rx:loop', 'c:state', 'b:state', 'x.absent:effector']);
    expect(tree.nodes.find((n) => n.id === 'loop.rx')?.keys).toEqual(['rx.s1', 'rx.s2']);
    expect(tree.inner.get('loop.rx')?.map((r) => r.id)).toEqual(['r3']);
  });
  it('merges rows between the same two nodes and draws the most cautious class; a pass-through is NONE', () => {
    const ac = tree.edges.find((e) => e.from === 'a' && e.to === 'c');
    expect(ac?.rows.map((r) => r.id)).toEqual(['r6', 'r7']);
    expect(ac?.cls).toBe('FIT');
    expect(tree.edges.find((e) => e.to === 'loop.rx')?.cls).toBe('NONE');
    expect(drawClass(row('u', [], 'x', { consts: [{ name: 'Q', source: '—' }] }))).toBe('UNTAGGED');
  });
  it('an ABSENT edge keeps its audit id; the absent node its own', () => {
    const e = tree.edges.find((x) => x.to === 'x.absent');
    expect(e).toMatchObject({ cls: 'ABSENT', absent: 'research/44 L2-01' });
    expect(tree.nodes.find((n) => n.id === 'x.absent')?.absent).toBe('research/44 L2-01');
  });
  it('Tarjan: the loop a → reflex → b → a is one component; b → a is the feedback edge', () => {
    expect(tree.loops).toEqual([expect.arrayContaining(['a', 'loop.rx', 'b'])]);
    expect(tree.loops[0]).toHaveLength(3);
    expect(tree.edges.filter((e) => e.feedback).map((e) => `${e.from}>${e.to}`)).toEqual(['b>a']);
  });
  it('generations by longest path once the feedback edges are set aside', () => {
    expect(Object.fromEntries(generations(tree))).toEqual({ 'trigger.t': 0, a: 1, 'loop.rx': 2, c: 2, b: 3, 'x.absent': 4 });
  });
  it('components() on a plain cycle: one component, one feedback edge', () => {
    const r = components(['x', 'y', 'z'], [{ from: 'x', to: 'y' }, { from: 'y', to: 'z' }, { from: 'z', to: 'x' }], 'x');
    expect(r.sccs).toHaveLength(1);
    expect([...r.feedback]).toEqual([2]);
  });
});

/** Pinned per trigger (the picture the registry of R1 draws; a row added or reclassed moves these, deliberately).
 *  Re-recorded at 182 rows (main 8119ecd0, the EEG stack's ten rows neuro.eeg.*; it was 172): every trigger gains the
 *  two nodes eeg.cortex and eeg.signal and the edges cbfRel → eeg.cortex (neuro.eeg.cortex.metabolic) and
 *  eeg.cortex → eeg.signal (neuro.eeg.signal.cortex), +2 nodes +2 edges; ptxTension and peep also reach resp.o2.sa,
 *  so they gain resp.o2.sa → eeg.cortex (the same metabolic row), +2 nodes +3 edges. Feedback, absent, columns and the
 *  loop are unchanged (the EEG nodes lie after the loop and feed nothing back). */
const PINS = {
  'trigger.bleed': { nodes: 79, edges: 129, feedback: 4, absent: 17, columns: 20, loop: 53 },
  'trigger.drug.propofol': { nodes: 74, edges: 123, feedback: 14, absent: 17, columns: 23, loop: 53 },
  'trigger.drug.phenylephrine': { nodes: 75, edges: 127, feedback: 22, absent: 17, columns: 21, loop: 53 },
  'trigger.drug.esmolol': { nodes: 76, edges: 127, feedback: 13, absent: 17, columns: 20, loop: 53 },
  'trigger.lungCondition.ptxTension': { nodes: 93, edges: 153, feedback: 4, absent: 19, columns: 23, loop: 55 },
  'trigger.ventilation.peep': { nodes: 93, edges: 153, feedback: 27, absent: 19, columns: 32, loop: 55 },
} as const;

describe('the registry the page draws', () => {
  for (const [trigger, pin] of Object.entries(PINS)) {
    it(`${trigger}: ${pin.nodes} nodes, ${pin.edges} edges, ${pin.feedback} feedback, ${pin.absent} absent, ${pin.columns} columns`, () => {
      const tree = mechanismTree(REGISTRY, trigger);
      const L = layout(tree);
      expect({
        nodes: tree.nodes.length, edges: tree.edges.length, feedback: tree.edges.filter((e) => e.feedback).length,
        absent: tree.edges.filter((e) => e.absent).length, columns: L.gens.length, loop: tree.loops[0]?.length,
      }).toEqual(pin);
      expect(L.gens[0]).toEqual([trigger]);
      // no edge drawn forward runs backward or within a column
      for (const e of tree.edges.filter((x) => !x.feedback)) expect(L.at.get(e.to)!.gen).toBeGreaterThan(L.at.get(e.from)!.gen);
    });
  }
  it('propofol: Ce, the drug factors, then SVR; the baroreflex is one loop box of its five states', () => {
    const tree = mechanismTree(REGISTRY, 'trigger.drug.propofol');
    const L = layout(tree);
    expect(L.gens[1]).toEqual(['pk.bus.cns.propCe']);
    expect(L.gens[2]).toEqual(['pk.fx.svr', 'pk.fx.ees', 'pk.fx.v0Frac', 'pk.fx.gv', 'pk.fx.gvHr', 'pk.fx.symp', 'pk.fx.setF', 'pk.bus.cns.hypPropEq', 'pk.bus.cns.hypVentPropEq']);
    expect(L.gens[3]).toEqual(['hemo.circ.p.rSys', 'neuro.resp.hypnoticDep']);
    const baro = tree.nodes.filter((n) => n.kind === 'loop' && n.label === 'Baroreflex');
    expect(baro.map((n) => n.keys)).toEqual([['circ.baro.gains', 'hemo.circ.baro.mapLp', 'hemo.circ.baro.set', 'hemo.circ.baro.es', 'hemo.circ.baro.ev']]);
    for (const k of ['hemo.circ.p.v0Sv', 'mon.abpMean', 'hemo.circ.mapNow']) expect(tree.nodes.some((n) => n.id === k), k).toBe(true);
  });
  it('the whole view is the whole tree: the pins above hold for it unchanged', () => {
    for (const [trigger, pin] of Object.entries(PINS)) {
      const v = view(mechanismTree(REGISTRY, trigger), { whole: true });
      expect({ nodes: v.nodes.length, edges: v.edges.length, hidden: v.hidden, columns: layout(v).gens.length }, trigger).toEqual({ nodes: pin.nodes, edges: pin.edges, hidden: 0, columns: pin.columns });
    }
  });
  it('is stable: the same registry and trigger draw the same string', () => {
    const a = treeSvg(mechanismTree(REGISTRY, 'trigger.ventilation.peep')).svg;
    expect(treeSvg(mechanismTree(REGISTRY, 'trigger.ventilation.peep')).svg).toBe(a);
  });
});

// ---------- the readable view (brief 104) ----------
// T → a → b1…b8 (b1, b2 sourced; b3…b7 pass-throughs; b8 absent); b1 → c → d → e; d → mon.y and e → mon.x through the
// monitor module. Generations: T 0, a 1, b 2, c 3, d 4, e and mon.y 5, mon.x 6.
const V: TreeData = {
  triggers: [{ path: 'trigger.t', label: 'T' }],
  nodes: [{ path: 'trigger.t', kind: 'trigger', label: 'T' }, { path: 'mon.x', kind: 'observable', label: 'X' }, { path: 'mon.y', kind: 'observable', label: 'Y' }],
  rows: [
    row('v1', ['trigger.t'], 'a'),
    ...[1, 2, 3, 4, 5, 6, 7, 8].map((i) => row(`b${i}`, ['a'], `b${i}`, i <= 2 ? { cls: 'SOURCED', consts: [{ name: `K${i}`, value: '1', source: 'Guyton 1955' }] } : i === 8 ? { cls: 'ABSENT', absent: 'research/44 L2-01' } : {})),
    row('v2', ['b1'], 'c'),
    row('v3', ['c'], 'd'),
    row('v4', ['d'], 'e'),
    row('v5', ['e'], 'mon.x', { module: 'monitor' }),
    row('v6', ['d'], 'mon.y', { module: 'monitor' }),
  ],
};
const vt = mechanismTree(V, 'trigger.t', () => null, []);
const ids = (v: { nodes: { id: string }[] }) => v.nodes.map((n) => n.id);

describe('view(): the default view (depth P-1, the folds)', () => {
  it('P-1 is 4 generations, six children before the fold, routes two generations past the shortest', () => {
    expect([DEPTH, MAX_CHILDREN, PATH_SLACK]).toEqual([4, 6, 2]);
  });
  it('the device layer is the monitor module\'s targets', () => {
    expect(['mon.x', 'mon.y', 'e', 'trigger.t'].map((id) => deviceModule(vt, id))).toEqual(['monitor', 'monitor', null, null]);
  });
  const v = view(vt);
  it('draws the trigger and 4 generations past it; the strongest six of a\'s eight children, the rest in "2 more"', () => {
    expect(ids(v)).toEqual(['trigger.t', 'a', 'b1', 'b2', 'b3', 'b4', 'b5', 'b6', 'c', 'd', 'more.a']);
    const fold = v.nodes.find((n) => n.id === 'more.a');
    expect(fold).toMatchObject({ kind: 'fold', label: '2 more', keys: ['b7', 'b8'], of: 'a', names: ['b7', 'b8'] });
    expect(v.edges.find((e) => e.to === 'more.a')?.rows.map((r) => r.id)).toEqual(['b7', 'b8']);
    expect(v.hidden).toBe(vt.nodes.length - 10);
  });
  it('a node past the depth\'s edge carries "show more" with the count of its undrawn children (e and the monitor box)', () => {
    expect(v.nodes.filter((n) => n.more).map((n) => [n.id, n.more])).toEqual([['d', 2]]);
  });
  it('"show more" draws one generation from the node: e and the monitor box, folded', () => {
    const x = view(vt, { expanded: new Set(['d']) });
    expect(ids(x)).toEqual(['trigger.t', 'a', 'b1', 'b2', 'b3', 'b4', 'b5', 'b6', 'c', 'd', 'e', 'device.monitor', 'more.a']);
    expect(x.nodes.find((n) => n.id === 'device.monitor')).toMatchObject({ kind: 'device', label: 'Monitor values', keys: ['mon.y', 'mon.x'] });
    expect(x.edges.filter((e) => e.to === 'device.monitor').map((e) => e.from)).toEqual(['e', 'd']);
    expect(x.nodes.filter((n) => n.more)).toEqual([]);
  });
  it('opening the monitor box draws its values; opening "n more" draws the folded children (the strongest order kept)', () => {
    const half = view(vt, { expanded: new Set(['d']), opened: new Set(['device.monitor']) });
    expect(half.nodes.filter((n) => n.more).map((n) => [n.id, n.more])).toEqual([['e', 1]]); // mon.x is generation 6
    const x = view(vt, { expanded: new Set(['d', 'e']), opened: new Set(['device.monitor', 'more.a']) });
    expect(ids(x)).toEqual(['trigger.t', 'a', 'b1', 'b2', 'b3', 'b4', 'b5', 'b6', 'b7', 'b8', 'c', 'd', 'e', 'mon.y', 'mon.x']);
    expect(x.hidden).toBe(0);
  });
  it('the strongest by class: sourced first, absent last, ties in registry order', () => {
    const shown = view(vt, { maxChildren: 3 }).nodes.filter((n) => n.id.startsWith('b')).map((n) => n.id);
    expect(shown).toEqual(['b1', 'b2', 'b3']);
  });
});

describe('view(): path to…, and the whole tree', () => {
  it('keeps the route from the trigger to the target, the depth and folds aside', () => {
    const p = view(vt, { pathTo: 'mon.x' });
    expect(ids(p)).toEqual(['trigger.t', 'a', 'b1', 'c', 'd', 'e', 'mon.x']);
    expect(p.edges.map((e) => `${e.from}>${e.to}`)).toEqual(['trigger.t>a', 'a>b1', 'b1>c', 'c>d', 'd>e', 'e>mon.x']);
  });
  it('a route longer than the shortest by more than the slack is dropped', () => {
    // T → p → q → r → z (4) and T → z (1): with slack 2 only the direct edge stays
    const W: TreeData = { triggers: [], nodes: [], rows: [row('w1', ['trigger.t'], 'p'), row('w2', ['p'], 'q'), row('w3', ['q'], 'r'), row('w4', ['r'], 'z'), row('w5', ['trigger.t'], 'z')] };
    const w = mechanismTree(W, 'trigger.t', () => null, []);
    expect(ids(view(w, { pathTo: 'z' }))).toEqual(['trigger.t', 'z']);
    expect(ids(view(w, { pathTo: 'z', slack: 3 }))).toEqual(['trigger.t', 'p', 'z', 'q', 'r']);
  });
  it('no route: the trigger alone', () => {
    expect(ids(view(vt, { pathTo: 'nowhere' }))).toEqual(['trigger.t']);
  });
  it('the whole view draws every node and edge of the tree', () => {
    const w = view(vt, { whole: true });
    expect([w.nodes.length, w.edges.length, w.hidden]).toEqual([vt.nodes.length, vt.edges.length, 0]);
  });
});

/** The default view per trigger (brief 104): what the page opens on. Measured fit at 1440 × 900 and on A4 in
 *  e2e/mechanism-tree.e2e.ts. The whole tree keeps PINS above. */
const DEFAULT_PINS = {
  'trigger.bleed': { nodes: 6, edges: 5, columns: 5, tallest: 2, frontier: 2, folds: 0 },
  'trigger.drug.propofol': { nodes: 13, edges: 12, columns: 5, tallest: 7, frontier: 5, folds: 1 },
  'trigger.drug.phenylephrine': { nodes: 8, edges: 7, columns: 5, tallest: 3, frontier: 5, folds: 0 },
  'trigger.drug.esmolol': { nodes: 12, edges: 13, columns: 5, tallest: 6, frontier: 6, folds: 0 },
  'trigger.lungCondition.ptxTension': { nodes: 12, edges: 11, columns: 5, tallest: 4, frontier: 5, folds: 0 },
  'trigger.ventilation.peep': { nodes: 11, edges: 10, columns: 5, tallest: 4, frontier: 4, folds: 0 },
} as const;

describe('the default view of the registry the page draws', () => {
  for (const [trigger, pin] of Object.entries(DEFAULT_PINS)) {
    it(`${trigger}: ${pin.nodes} nodes in ${pin.columns} columns; every node has a clinical label; a route to the MAP`, () => {
      const tree = mechanismTree(REGISTRY, trigger, clinicalLabel);
      const v = view(tree);
      const L = layout(v);
      expect({ nodes: v.nodes.length, edges: v.edges.length, columns: L.gens.length, tallest: Math.max(...L.gens.map((g) => g.length)), frontier: v.nodes.filter((n) => n.more).length, folds: v.nodes.filter((n) => n.kind === 'fold').length }).toEqual(pin);
      expect(L.gens.length).toBeLessThanOrEqual(DEPTH + 1);
      for (const n of tree.nodes) if (n.kind !== 'loop') expect(n.label, n.id).not.toBe(n.id);
      const p = view(tree, { pathTo: 'mon.abpMean' });
      expect(ids(p)).toContain('mon.abpMean');
      expect(ids(p)[0]).toBe(trigger);
      expect(p.nodes.length).toBeGreaterThan(2);
    });
  }
  it('expanding every frontier node, repeatedly, reaches the whole tree', () => {
    for (const trigger of Object.keys(DEFAULT_PINS)) {
      const tree = mechanismTree(REGISTRY, trigger);
      const expanded = new Set<string>();
      const opened = new Set<string>(['device.monitor']);
      for (let i = 0; i < 40; i++) {
        const v = view(tree, { expanded, opened });
        for (const n of v.nodes) n.more ? expanded.add(n.id) : n.kind === 'fold' && opened.add(n.id);
        if (!v.hidden) break;
      }
      expect(view(tree, { expanded, opened }).hidden, trigger).toBe(0);
    }
  });
});
